const json=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store'}});
export async function telegram(request,send=fetch){
 if(request.method!=='POST')return json({error:'Chỉ hỗ trợ POST.'},405);
 const url=new URL(request.url);
 if(request.headers.get('origin')!==url.origin)return json({error:'Yêu cầu phải đến từ ứng dụng.'},403);
 if(!request.headers.get('content-type')?.startsWith('application/json'))return json({error:'Dữ liệu không hợp lệ.'},415);
 if(Number(request.headers.get('content-length'))>12000)return json({error:'Nội dung quá dài.'},413);
 let body;try{const raw=await request.text();if(raw.length>12000)return json({error:'Nội dung quá dài.'},413);body=JSON.parse(raw)}catch{return json({error:'Dữ liệu không hợp lệ.'},400)}
 const {token,channel,text}=body??{};
 if(typeof token!=='string'||!/^\d{5,20}:[A-Za-z0-9_-]{20,120}$/.test(token))return json({error:'Bot Token không đúng định dạng.'},400);
 if(typeof channel!=='string'||!/^(@[A-Za-z][A-Za-z0-9_]{4,31}|-100\d{5,20})$/.test(channel))return json({error:'Nhập @username channel hoặc ID dạng -100…'},400);
 if(typeof text!=='string'||!text.startsWith('BINANCE MARKET BREADTH\n')||text.length>4000)return json({error:'Nội dung báo cáo không hợp lệ.'},400);
 try{const res=await send(`https://api.telegram.org/bot${token}/sendMessage`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chat_id:channel,text}),signal:AbortSignal.timeout(15000)});const result=await res.json();
 if(!res.ok||!result.ok){const code=result.error_code??res.status;const error=code===401?'Bot Token không hợp lệ.':code===403?'Bot chưa có quyền đăng bài trong channel.':code===429?'Telegram giới hạn tốc độ. Vui lòng đợi rồi thử lại.':'Không gửi được. Kiểm tra Channel ID và quyền quản trị viên của bot.';return json({error},502)}
 return json({ok:true});
 }catch{return json({error:'Chưa xác nhận được kết quả gửi. Kiểm tra channel trước khi thử lại để tránh gửi trùng.'},502)}
}

const assets={"/index.html":{"body":"<!doctype html><html lang=\"vi\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Binance · Market Breadth</title><link rel=\"stylesheet\" href=\"style.css\"><body><header><a class=\"brand\" href=\"#\">◈ <b>BINANCE</b><span> / Market Breadth</span></a><span class=\"pill\">SPOT MARKET · USDT</span></header><main><div class=\"eyebrow\">TỔNG QUAN THỊ TRƯỜNG</div><h1>Thị trường đang<br><em>nghiêng về đâu?</em></h1><p class=\"intro\">Đo độ rộng thị trường qua xu hướng dài hạn và động lượng của các coin trên Binance.</p><section class=\"toolbar\"><div><label>Phạm vi</label><select id=\"scope\"><option value=\"all\">Tất cả coin / USDT</option><option value=\"100\">Top 100 theo khối lượng</option><option value=\"50\">Top 50 theo khối lượng</option></select></div><div><label>Nến tuần & tháng</label><select id=\"mode\"><option value=\"closed\">Đã đóng (ổn định)</option><option value=\"live\">Gồm nến đang chạy</option></select></div><label class=\"check\"><input id=\"stable\" type=\"checkbox\" checked> Loại stablecoin</label><button id=\"refresh\">↻ Cập nhật dữ liệu</button></section><div class=\"status\"><span id=\"status\">Sẵn sàng kết nối dữ liệu công khai Binance</span><span id=\"updated\">Chưa cập nhật</span></div><div class=\"progress\"><div id=\"bar\"></div></div><section class=\"cards\" id=\"cards\"></section><section class=\"telegram\"><div class=\"eyebrow\">CHIA SẺ KẾT QUẢ</div><h2>Gửi lên Telegram</h2><p>Nhập Bot Token và channel đích. Bấm “Lưu cấu hình” để nhớ token và channel trên trình duyệt này. Chỉ lưu trên máy bạn tin cậy. Bot cần quyền quản trị viên đăng bài trong channel.</p><div class=\"telegram-fields\"><div><label for=\"bot-token\">Bot Token</label><input type=\"password\" id=\"bot-token\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Nhập token từ @BotFather\"></div><div><label for=\"channel-id\">Channel ID / Username</label><input id=\"channel-id\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"@ten_channel hoặc -100…\"></div><button id=\"send-telegram\" disabled>Gửi kết quả lên Telegram</button></div><div class=\"telegram-config-actions\"><button id=\"save-telegram\" type=\"button\">Lưu cấu hình</button><button id=\"clear-telegram\" type=\"button\">Xóa cấu hình</button><span id=\"telegram-config-status\" role=\"status\">Chưa lưu cấu hình trên trình duyệt này.</span></div><p id=\"telegram-status\" role=\"status\">Quét hoàn tất để gửi báo cáo gồm 6 chỉ số.</p><details><summary>Xem trước tin nhắn</summary><pre id=\"telegram-preview\">Chưa có kết quả quét.</pre></details></section><section class=\"details\"><div class=\"sectionhead\"><div><div class=\"eyebrow\">KHÁM PHÁ DỮ LIỆU</div><h2>Chi tiết từng coin</h2></div><input id=\"search\" placeholder=\"Tìm coin, ví dụ BTC…\" aria-label=\"Tìm coin\"></div><div class=\"filters\" id=\"filters\"><button data-filter=\"all\" class=\"selected\">Tất cả</button><button data-filter=\"ema\">Giá > EMA200</button><button data-filter=\"ma\">Giá > MA200</button><button data-filter=\"week\">MACD tuần > 0</button><button data-filter=\"month\">MACD tháng > 0</button><button data-filter=\"ma50\">MA50 > MA200</button><button data-filter=\"weekHigh\">Vượt đỉnh tuần trước</button><button data-filter=\"error\">Lỗi tải</button></div><div class=\"tablewrap\"><table><thead><tr><th>Coin / USDT</th><th>Giá hiện tại</th><th>EMA200 ngày</th><th>MA200 ngày</th><th>MACD tuần</th><th>MACD tháng</th><th>MA50 ngày</th><th>Đỉnh tuần trước</th></tr></thead><tbody id=\"rows\"></tbody></table></div><div id=\"empty\">Nhấn “Cập nhật dữ liệu” để quét thị trường.</div><div id=\"foot\"></div></section><details><summary>Cách tính & nguồn dữ liệu</summary><p>Mỗi coin được đếm một lần qua cặp Spot USDT đang giao dịch. Có thể loại stablecoin bằng danh sách cố định (USDC, FDUSD, TUSD, USDP, DAI, USDD, USD1, USTC, BUSD, USDE, USDS, AEUR, EURI, RLUSD, BFUSD); danh sách này có thể chưa đầy đủ.</p><p>Giá lấy từ ticker hiện tại. MA50 > MA200 dùng trung bình 50 và 200 giá đóng cửa ngày đã đóng, cần ít nhất 200 nến ngày. Vượt đỉnh tuần nghĩa là giá hiện tại lớn hơn giá High của nến tuần gần nhất đã đóng theo UTC; không phụ thuộc tùy chọn nến MACD. Điều kiện dùng dấu >, giá bằng đỉnh không được đếm. MA200 là trung bình 200 giá đóng cửa ngày đã đóng; EMA200 khởi tạo bằng SMA200 rồi cập nhật trên tối đa 1.000 nến ngày gần nhất. MACD là EMA12 − EMA26, không phải histogram. Hai EMA khởi tạo bằng SMA tương ứng; cần ít nhất 26 nến tuần/tháng. Tham số truyền thống 12/26/9, signal 9 không ảnh hưởng điều kiện MACD > 0.</p><p>Nến ngày luôn dùng nến đã đóng theo UTC. Nến tuần/tháng mặc định đã đóng, có tùy chọn gồm nến hiện hành. Mẫu số của mỗi chỉ số chỉ gồm coin đủ lịch sử và tải thành công. Lỗi được hiển thị riêng, không tính như tín hiệu âm. Số liệu đang quét là kết quả một phần, không phải tổng thị trường.</p><p>Dữ liệu tải trực tiếp từ <a href=\"https://developers.binance.com/en/docs/products/spot/rest-api\" target=\"_blank\" rel=\"noreferrer\">Binance Public Market Data API</a>, không cần API key. Trình duyệt/mạng có thể bị giới hạn truy cập hoặc giới hạn tốc độ; ứng dụng sẽ báo lỗi và cho phép thử lại. Giá và nến tải tại các thời điểm khác nhau trong lượt quét.</p></details><footer>BINANCE MARKET BREADTH <span>Dữ liệu thị trường · Không phải lời khuyên đầu tư</span></footer></main><script type=\"module\" src=\"app.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/style.css":{"body":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');\n:root{color-scheme:dark;--bg:#0c1013;--panel:#151a1e;--line:#293136;--muted:#8b999f;--gold:#f2cc62;--green:#79d5b0}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e7eeec;font-family:'DM Sans',sans-serif}header{height:82px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;padding:0 5vw}.brand{color:var(--gold);text-decoration:none;font-size:22px;letter-spacing:1px}.brand span{color:var(--muted);font-size:14px;letter-spacing:0}.pill{font-size:11px;letter-spacing:1.5px;color:var(--muted);border:1px solid var(--line);padding:9px 12px;border-radius:20px}main{max-width:1400px;margin:auto;padding:54px 5vw 25px}.eyebrow{font-size:10px;letter-spacing:2.6px;color:var(--gold);font-weight:700}h1{font-family:'Space Grotesk',sans-serif;font-size:clamp(38px,5vw,64px);line-height:1.07;letter-spacing:-3px;font-weight:500;margin:21px 0}h1 em{font-style:normal;color:var(--gold)}.intro{color:var(--muted);font-size:15px;line-height:1.7;max-width:610px}.toolbar{display:flex;align-items:end;gap:16px;background:var(--panel);border:1px solid var(--line);padding:20px;margin-top:34px;border-radius:12px}.toolbar>div{min-width:200px}label{font-size:11px;color:var(--muted);display:block;margin-bottom:8px}select,input,button{font:inherit}select,#search{background:#0d1215;color:#e7eeec;border:1px solid #364047;border-radius:6px;padding:11px;max-width:100%;outline-color:var(--gold)}select{width:100%;font-size:13px}.check{display:flex;align-items:center;gap:6px;margin:0 auto 12px 0;white-space:nowrap}input[type=checkbox]{accent-color:var(--gold)}button{cursor:pointer}#refresh{background:var(--gold);border:0;padding:13px 18px;border-radius:6px;font-weight:700;font-size:13px;white-space:nowrap}button:disabled{opacity:.5;cursor:wait}.status{display:flex;justify-content:space-between;color:var(--muted);font-size:11px;margin:19px 0 10px;gap:20px}.progress{background:#20292d;height:3px;border-radius:3px;overflow:hidden;margin-bottom:24px}#bar{background:var(--gold);height:100%;width:0;transition:width .3s}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{border:1px solid var(--line);background:linear-gradient(140deg,#1b2226,#14191d);padding:23px;border-radius:10px}.card .top{display:flex;justify-content:space-between;font-size:12px;color:#c4cfcc}.card .index{color:#617078}.num{font:500 48px 'Space Grotesk',sans-serif;margin:20px 0 8px;letter-spacing:-2px}.num small{font:12px 'DM Sans',sans-serif;letter-spacing:0;color:var(--muted);margin-left:6px}.ratio{font-size:12px;color:var(--green)}.track{background:#2a3437;height:5px;margin-top:17px;border-radius:5px;overflow:hidden}.fill{height:100%;background:var(--green)}.caption{font-size:10px;color:var(--muted);margin-top:12px}.details{margin-top:37px;border:1px solid var(--line);border-radius:12px;background:var(--panel);overflow:hidden}.sectionhead{display:flex;align-items:center;justify-content:space-between;padding:24px}h2{font:500 22px 'Space Grotesk',sans-serif;margin:10px 0 0;letter-spacing:-.5px}#search{font-size:12px;width:220px}.filters{display:flex;gap:8px;padding:0 24px 22px;flex-wrap:wrap}.filters button{border:1px solid var(--line);background:transparent;color:var(--muted);padding:8px 12px;border-radius:5px;font-size:11px}.filters button.selected{border-color:var(--gold);color:var(--gold);background:#f2cc620b}.tablewrap{overflow:auto;max-height:530px}table{border-collapse:collapse;width:100%;white-space:nowrap}th{position:sticky;top:0;background:#1c2428;color:var(--muted);font-weight:400;font-size:11px;text-align:right;padding:14px 20px}td{text-align:right;font-size:12px;padding:15px 20px;border-top:1px solid var(--line);font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left}td b{font-size:13px}td small{color:var(--muted);font-size:10px}.positive{color:var(--green)}.negative{color:#eaa2a2}.na{color:#718087}#empty{text-align:center;padding:52px;color:var(--muted);font-size:13px}#foot{padding:14px 24px;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}details{margin-top:25px;color:var(--muted);font-size:12px;line-height:1.8}summary{cursor:pointer;color:#ced6d3}a{color:var(--gold)}footer{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding-top:24px;margin-top:35px;font-size:10px;letter-spacing:1px;color:#69797f}footer span{letter-spacing:0}@media(max-width:1000px){.toolbar{flex-wrap:wrap}.toolbar>div{flex:1}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){header{height:65px}.brand span,.pill{display:none}main{padding-top:35px}h1{letter-spacing:-1.5px}.toolbar>div{min-width:100%;}.check{margin:8px 0}.toolbar button{width:100%}.cards{gap:10px}.card{padding:16px}.num{font-size:38px}.sectionhead{align-items:start;gap:20px;flex-direction:column}#search{width:100%}.status{flex-direction:column;gap:5px}footer{gap:20px;line-height:1.7}}\n\n.telegram{margin-top:30px;border:1px solid var(--line);background:var(--panel);border-radius:12px;padding:24px}.telegram p{color:var(--muted);font-size:12px;line-height:1.7}.telegram-fields{display:flex;align-items:end;gap:16px;margin-top:20px}.telegram-fields>div{flex:1}.telegram-fields input{width:100%;background:#0d1215;color:#e7eeec;border:1px solid #364047;border-radius:6px;padding:12px;font-size:13px}.telegram button{padding:13px 18px;background:var(--gold);border:0;border-radius:6px;font-size:13px;font-weight:700}#telegram-preview{white-space:pre-wrap;line-height:1.8;color:#c4cfcc}#telegram-status{min-height:20px}@media(max-width:800px){.telegram-fields{align-items:stretch;flex-direction:column}}\n\n.telegram-config-actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-top:16px}.telegram-config-actions button{background:transparent;border:1px solid var(--line);color:#e7eeec;padding:9px 14px}.telegram-config-actions #save-telegram{border-color:var(--gold);color:var(--gold)}#telegram-config-status{color:var(--muted);font-size:11px;line-height:1.6}\n","type":"text/css"},"/app.js":{"body":"import {ema,sma,macd,closes,previousWeekHigh} from './indicators.mjs';\nconst $=id=>document.getElementById(id), keys=['ema','ma','week','month','ma50','weekHigh'],labels=['Giá > EMA200 ngày','Giá > MA200 ngày','MACD tuần > 0','MACD tháng > 0','MA50 > MA200 ngày','Giá > đỉnh tuần trước'];\nconst stable=new Set('USDC FDUSD TUSD USDP DAI USDD USD1 USTC BUSD USDE USDS AEUR EURI RLUSD BFUSD'.split(' '));\nlet data=[],filter='all',total=0,completed=0,running=false,limited=false,report=null,sending=false;\nconst sleep=ms=>new Promise(r=>setTimeout(r,ms));\nasync function api(path){for(let attempt=0;attempt<3;attempt++){if(limited)throw Error('Binance giới hạn truy cập');try{const response=await fetch('https://data-api.binance.vision/api/v3/'+path,{signal:AbortSignal.timeout(20000)});if(response.status===429||response.status===418){limited=true;throw Error('Binance giới hạn tốc độ (HTTP '+response.status+'). Vui lòng đợi vài phút rồi thử lại.')}if(!response.ok)throw Error('Binance HTTP '+response.status);return await response.json()}catch(e){if(limited||attempt===2)throw e;await sleep(1000*(attempt+1))}}}\nfunction number(v){return v==null?'—':v.toLocaleString('en-US',{maximumSignificantDigits:7})}\nfunction eligible(r,key){return r[key]!=null&&(key!=='ma50'||r.ma!=null)}\nfunction qualifies(r,key){return eligible(r,key)&&(key==='ma50'?r.ma50>r.ma:['ema','ma','weekHigh'].includes(key)?r.price>r[key]:r[key]>0)}\nfunction render(){\n $('cards').innerHTML=keys.map((key,i)=>{const valid=data.filter(r=>eligible(r,key)),count=valid.filter(r=>qualifies(r,key)).length,pct=valid.length?count/valid.length*100:0;return `<article class=\"card\"><div class=\"top\"><span>${labels[i]}</span><span class=\"index\">0${i+1}</span></div><div class=\"num\">${valid.length?count:'—'}<small>coin</small></div><div class=\"ratio\">${valid.length?pct.toFixed(1)+'%':'—'} <span class=\"na\">/ ${valid.length} đủ dữ liệu</span></div><div class=\"track\"><div class=\"fill\" style=\"width:${pct}%\"></div></div><div class=\"caption\">${running?'Đang quét · kết quả một phần':data.length?'Kết quả lượt quét gần nhất':'Chưa có dữ liệu'} · ${data.filter(r=>!r.error&&!eligible(r,key)).length} thiếu lịch sử</div></article>`}).join('');\n const q=$('search').value.toUpperCase().trim(),visible=data.filter(r=>r.base.toUpperCase().includes(q)&&(filter==='all'||(filter==='error'?r.error:qualifies(r,filter)))).sort((a,b)=>b.volume-a.volume);\n $('rows').replaceChildren();for(const r of visible){const tr=document.createElement('tr'),coin=document.createElement('td'),b=document.createElement('b');b.textContent=r.base;coin.append(b,document.createTextNode(' / USDT'));if(r.error){const hint=document.createElement('small');hint.textContent=' · Lỗi tải';hint.title=r.error;coin.append(hint)}tr.append(coin);const price=document.createElement('td');price.textContent=number(r.price);tr.append(price);for(const key of keys){const td=document.createElement('td');td.textContent=number(r[key]);td.className=!eligible(r,key)?'na':qualifies(r,key)?'positive':'negative';tr.append(td)}$('rows').append(tr)}\n $('empty').style.display=visible.length?'none':'block';$('empty').textContent=data.length?'Không có coin phù hợp bộ lọc.':'Nhấn “Cập nhật dữ liệu” để quét thị trường.';\n $('foot').textContent=`${visible.length} hiển thị · ${completed}/${total} đã xử lý · ${data.filter(r=>r.error).length} coin có lỗi tải`;\n $('bar').style.width=total?(completed/total*100)+'%':'0';\n}\nasync function scan(){if(running)return;running=true;limited=false;report=null;$('send-telegram').disabled=true;$('telegram-preview').textContent='Quét đang chạy…';$('telegram-status').textContent='Đợi quét hoàn tất để gửi báo cáo.';data=[];completed=0;total=0;render();$('refresh').disabled=true;$('scope').disabled=$('mode').disabled=$('stable').disabled=true;$('status').textContent='Đang lấy danh sách coin và giá hiện tại…';$('updated').textContent='Đang cập nhật';\n const scope=$('scope').value,live=$('mode').value==='live',exclude=$('stable').checked;\n try{const [info,tickers]=await Promise.all([api('exchangeInfo'),api('ticker/24hr')]);const quotes=new Map(tickers.map(t=>[t.symbol,t]));let symbols=info.symbols.filter(s=>s.status==='TRADING'&&s.quoteAsset==='USDT'&&s.isSpotTradingAllowed!==false&&(!exclude||!stable.has(s.baseAsset))&&quotes.has(s.symbol)).sort((a,b)=>Number(quotes.get(b.symbol).quoteVolume)-Number(quotes.get(a.symbol).quoteVolume));if(scope!=='all')symbols=symbols.slice(0,Number(scope));total=symbols.length;let cursor=0;\n async function worker(){while(cursor<symbols.length&&!limited){const s=symbols[cursor++],t=quotes.get(s.symbol),r={base:s.baseAsset,price:Number(t.lastPrice),volume:Number(t.quoteVolume),ema:null,ma:null,week:null,month:null,ma50:null,weekHigh:null};const results=await Promise.allSettled([api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1d&limit=1000`),api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1w&limit=1000`),api(`klines?symbol=${encodeURIComponent(s.symbol)}&interval=1M&limit=1000`)]);const now=Date.now();if(results[0].status==='fulfilled'){const c=closes(results[0].value,false,now);r.ema=ema(c,200);r.ma=sma(c,200);r.ma50=sma(c,50)}if(results[1].status==='fulfilled'){r.week=macd(closes(results[1].value,live,now));r.weekHigh=previousWeekHigh(results[1].value,now)}if(results[2].status==='fulfilled')r.month=macd(closes(results[2].value,live,now));const errors=results.filter(v=>v.status==='rejected');if(errors.length)r.error=errors.map(e=>e.reason.message).join('; ');data.push(r);completed++;$('status').textContent=`Đang quét ${completed}/${total} coin · ${s.baseAsset} · Kết quả một phần`;render();await sleep(650)}}\n await Promise.all([worker(),worker()]);$('status').textContent=limited?`Đã dừng do giới hạn Binance. Kết quả một phần: ${completed}/${total} coin.`:`Hoàn tất ${completed}/${total} coin${data.some(r=>r.error)?' · Có lỗi tải, xem bộ lọc Lỗi tải':''}`;$('updated').textContent='Cập nhật '+new Date().toLocaleString('vi-VN');\n if(!limited&&completed===total&&total>0){const lines=keys.map((key,i)=>{const valid=data.filter(r=>eligible(r,key)),count=valid.filter(r=>qualifies(r,key)).length;return `${i+1}. ${labels[i]}: ${count}/${valid.length} coin (${valid.length?(count/valid.length*100).toFixed(1):'—'}%)`});report=['BINANCE MARKET BREADTH',new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' (giờ Việt Nam)','Binance Spot / USDT · '+(scope==='all'?'Tất cả coin':'Top '+scope+' theo khối lượng'),'Stablecoin: '+(exclude?'Loại':'Gồm'),'Nến MACD tuần/tháng: '+(live?'Gồm nến đang chạy':'Đã đóng'),`Đã xử lý: ${completed}/${total} · Coin lỗi tải: ${data.filter(r=>r.error).length}`,'',...lines,'','Mẫu số chỉ gồm coin đủ dữ liệu và tải thành công cho từng chỉ số.','Vượt đỉnh tuần = giá hiện tại > High tuần trước đã đóng.'].join('\\n');$('telegram-preview').textContent=report;$('telegram-status').textContent='Báo cáo sẵn sàng. Kiểm tra channel và bấm gửi.';$('send-telegram').disabled=sending}else{$('telegram-status').textContent='Lượt quét chưa hoàn tất. Vui lòng quét lại trước khi gửi.'}\n\n }catch(e){$('status').textContent='Không tải được dữ liệu: '+e.message+'. Kiểm tra kết nối và thử lại.';$('updated').textContent='Cập nhật thất bại'}finally{running=false;$('refresh').disabled=false;$('scope').disabled=$('mode').disabled=$('stable').disabled=false;render()}}\n$('refresh').addEventListener('click',scan);$('search').addEventListener('input',render);$('filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('.filters button').forEach(x=>x.classList.toggle('selected',x===b));render()});render();\n\n$('send-telegram').addEventListener('click',async()=>{\n if(!report||running||sending)return;\n const token=$('bot-token').value.trim(),channel=$('channel-id').value.trim();\n if(!token||!channel){$('telegram-status').textContent='Vui lòng nhập Bot Token và Channel ID.';return}\n const text=report;sending=true;$('send-telegram').disabled=true;$('refresh').disabled=true;$('telegram-status').textContent='Đang gửi báo cáo lên '+channel+'…';\n try{const response=await fetch('/api/telegram',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,channel,text})});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Không gửi được báo cáo.');$('telegram-status').textContent='Đã gửi báo cáo thành công lên '+channel+'.'}catch(e){$('telegram-status').textContent=e.message==='Failed to fetch'?'Chưa xác nhận được kết quả gửi. Kiểm tra channel trước khi thử lại.':e.message}finally{sending=false;$('send-telegram').disabled=!report||running;$('refresh').disabled=running}\n});\n\nconst telegramConfigKey='binance-breadth.telegram-config.v1';\nfunction restoreTelegramConfig(){\n try{const raw=localStorage.getItem(telegramConfigKey);if(!raw)return;const saved=JSON.parse(raw);if(typeof saved.token!=='string'||typeof saved.channel!=='string')throw Error('invalid');$('bot-token').value=saved.token;$('channel-id').value=saved.channel;$('telegram-config-status').textContent='Đã tải cấu hình lưu trên trình duyệt này.'}\n catch{$('telegram-config-status').textContent='Không đọc được cấu hình đã lưu. Bạn có thể nhập lại và lưu.'}\n}\n$('save-telegram').addEventListener('click',()=>{\n const token=$('bot-token').value.trim(),channel=$('channel-id').value.trim();\n if(!/^\\d{5,20}:[A-Za-z0-9_-]{20,120}$/.test(token)||!/^(@[A-Za-z][A-Za-z0-9_]{4,31}|-100\\d{5,20})$/.test(channel)){$('telegram-config-status').textContent='Nhập Bot Token và Channel ID hợp lệ trước khi lưu.';return}\n try{localStorage.setItem(telegramConfigKey,JSON.stringify({token,channel}));$('telegram-config-status').textContent='Đã lưu. Lần sau mở trang sẽ tự điền Bot Token và Channel ID.'}\n catch{$('telegram-config-status').textContent='Trình duyệt không cho phép lưu. Bạn vẫn có thể nhập và gửi trong phiên này.'}\n});\n$('clear-telegram').addEventListener('click',()=>{\n $('bot-token').value='';$('channel-id').value='';\n try{localStorage.removeItem(telegramConfigKey);$('telegram-config-status').textContent='Đã xóa Bot Token và Channel ID đã lưu.'}\n catch{$('telegram-config-status').textContent='Đã xóa ô nhập nhưng không xóa được dữ liệu lưu. Hãy xóa dữ liệu trang trong cài đặt trình duyệt.'}\n});\nfor(const id of ['bot-token','channel-id'])$(id).addEventListener('input',()=>{$('telegram-config-status').textContent='Cấu hình đã thay đổi. Bấm Lưu cấu hình để nhớ thông tin mới.'});\nrestoreTelegramConfig();\n","type":"application/javascript"},"/indicators.mjs":{"body":"export function ema(values, period) {\n  if(values.length<period) return null;\n  let result=values.slice(0,period).reduce((a,b)=>a+b,0)/period;\n  for(let i=period;i<values.length;i++) result+=(values[i]-result)*2/(period+1);\n  return result;\n}\nexport function sma(values, period) {return values.length<period?null:values.slice(-period).reduce((a,b)=>a+b,0)/period}\nexport function macd(values){return values.length<26?null:ema(values,12)-ema(values,26)}\nexport function closes(klines,includeLive=false,now=Date.now()){return klines.filter(k=>includeLive||Number(k[6])<now).map(k=>Number(k[4]))}\n\nexport function previousWeekHigh(klines,now=Date.now()){const closed=klines.filter(k=>Number(k[6])<now);return closed.length?Number(closed.at(-1)[2]):null}\n","type":"application/javascript"}};
export default {async fetch(request){const path=new URL(request.url).pathname;if(path==='/api/telegram')return telegram(request);const asset=assets[path==='/'?'/index.html':path];if(!asset)return new Response('Not found',{status:404});return new Response(asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store'}})}};